import {
	TASK_RETRY_STATES,
	retryStateOf,
	isRetryingTask,
	retryProgressLabel,
	retryWaitLabel,
	clearRetryState,
	setRetryScheduled,
	isRetryStuck,
} from '../../../../shared/taskRetryState.js';

export {
	TASK_RETRY_STATES,
	retryStateOf,
	isRetryingTask,
	retryProgressLabel,
	retryWaitLabel,
	clearRetryState,
	setRetryScheduled,
	isRetryStuck,
};

import {
	retryStateOf as sharedRetryStateOf,
	isRetryingTask as sharedIsRetryingTask,
	retryProgressLabel as sharedRetryProgressLabel,
	retryWaitLabel as sharedRetryWaitLabel,
	clearRetryState as sharedClearRetryState,
	setRetryScheduled as sharedSetRetryScheduled,
	isRetryStuck as sharedIsRetryStuck,
	TASK_RETRY_STATES,
} from "../../shared/taskRetryState.js";

/***
 * MARK: taskRetryState (backend mirror)
 * @description Task-store-aware retry-state helpers, backed by the shared
 *   `shared/taskRetryState.js` implementation so backend and frontend never
 *   drift.
 * @example readRetryState({ status: "failed", autoRetrying: true }) => { state: "exhausted" }
 ***/
export { TASK_RETRY_STATES };

/***
 * @example readRetryState({ autoRetrying: true, status: "in_stage" }) => { state: "scheduled" }
 ***/
export const readRetryState = (task) => {
	return sharedRetryStateOf(task);
}

/***
 * @example isRetryingTask({ retryState: "running", status: "in_stage" }) => true
 ***/
export const isRetryingTask = sharedIsRetryingTask;

/***
 * @example retryProgressLabel({ retryState: "scheduled", autoRetrying: true, status: "in_stage" }) => "RETRYING (scheduled)"
 ***/
export const retryProgressLabel = sharedRetryProgressLabel;

/***
 * @example retryWaitLabel({ retryState: "scheduled", status: "in_stage", nextRetryAt: "2020-01-01T00:00:00.000Z" }, 1e13) => "due now"
 ***/
export const retryWaitLabel = sharedRetryWaitLabel;

/***
 * @example isRetryStuck({ retryState: "scheduled", nextRetryAt: "2020-01-01T00:00:00.000Z", status: "in_stage" }, 1e13) => true
 ***/
export const isRetryStuck = sharedIsRetryStuck;

/***
 * @example setRetryScheduled({ getTask: () => ({ id: "t1" }) }, "p", "t1", { attempt: 2, maxAttempts: 5 }) => ({ retryState: "scheduled" })
 ***/
export const setRetryScheduled = (taskStore, projectId, taskId, meta = {}) => {
	const task = taskStore?.getTask?.(projectId, taskId);
	if (!task) return null;
	sharedSetRetryScheduled(task, meta);
	return task;
}

/***
 * @example clearRetryState({ getTask: () => ({ id: "t1", autoRetrying: true }) }, "p", "t1") => ({ autoRetrying: false })
 ***/
export const clearRetryState = (taskStore, projectId, taskId, opts = {}) => {
	const task = taskStore?.getTask?.(projectId, taskId);
	if (!task) return null;
	sharedClearRetryState(task, opts);
	return task;
}

/***
 * @example armRetry({ schedulerRunning: false, _dueRetryIds: new Set() }, { id: "t1" }, 1000, { attempt: 1, maxAttempts: 3 }) => false
 ***/
export const armRetry = (taskStore, task, delayMs, meta = {}) => {
	const delay = Math.max(0, Number(delayMs) || 0);
	const nextRetryAt = new Date(Date.now() + delay).toISOString();
	sharedSetRetryScheduled(task, {
		attempt: meta.attempt,
		maxAttempts: meta.maxAttempts,
		nextRetryAt,
	});
	if (meta.budgetSource) task.retryBudgetSource = meta.budgetSource;

	if (taskStore?.schedulerRunning) {
		const timer = setTimeout(() => {
			try {
				taskStore.scheduleTick?.().catch?.(() => {});
			} catch {}
		}, delay);
		try {
			timer?.unref?.();
		} catch {}
		task.retryScheduledInStandby = false;
		return true;
	}
	task.retryScheduledInStandby = true;
	taskStore._dueRetryIds = taskStore._dueRetryIds || new Set();
	taskStore._dueRetryIds.add(task.id);
	return false;
}

import { describe, it, expect, vi } from "vitest";
import {
	TASK_RETRY_STATES,
	retryStateOf,
	isRetryingTask,
	retryProgressLabel,
	retryWaitLabel,
	clearRetryState,
	setRetryScheduled,
	isRetryStuck,
} from "../../shared/taskRetryState.js";
import {
	readRetryState,
	setRetryScheduled as storeSetRetryScheduled,
	clearRetryState as storeClearRetryState,
	armRetry,
} from "./taskRetryState.js";

// Domain: Task retry state — the shared contract behind the RETRYING badge.
// A task is only "retrying" while a retry is scheduled or running; a parked
// failed task (even one with a stale legacy autoRetrying flag) is not.

describe("The Work: shared retry-state contract", () => {
	it("retryStateOf(null) is none with zeroed counts", () => {
		expect(retryStateOf(null)).toEqual({
			state: "none",
			attempt: 0,
			maxAttempts: 0,
			nextRetryAt: null,
			hasRetryableSchedule: false,
		});
	});

	it("legacy autoRetrying maps to scheduled for runnable tasks", () => {
		const info = retryStateOf({ autoRetrying: true, status: "in_stage" });
		expect(info.state).toBe(TASK_RETRY_STATES.SCHEDULED);
		expect(info.hasRetryableSchedule).toBe(false);
	});

	it("a parked failed task with a lingering autoRetrying flag is not retrying", () => {
		const task = { status: "failed", autoRetrying: true };
		expect(retryStateOf(task).state).toBe(TASK_RETRY_STATES.EXHAUSTED);
		expect(isRetryingTask(task)).toBe(false);
	});

	it("an explicit scheduled state on a failed task converts to exhausted", () => {
		const task = { status: "failed", retryState: "scheduled", autoRetrying: true };
		expect(retryStateOf(task).state).toBe(TASK_RETRY_STATES.EXHAUSTED);
		expect(isRetryingTask(task)).toBe(false);
	});

	it("paused/interrupted/blocked tasks are never retrying", () => {
		for (const status of ["paused", "interrupted", "blocked", "completed", "done", "passed"]) {
			expect(isRetryingTask({ status, retryState: "scheduled", autoRetrying: true })).toBe(false);
		}
	});

	it("scheduled and running tasks in_stage are retrying", () => {
		expect(isRetryingTask({ status: "in_stage", retryState: "scheduled" })).toBe(true);
		expect(isRetryingTask({ status: "in_stage", retryState: "running" })).toBe(true);
		expect(isRetryingTask({ status: "in_stage", retryState: "none" })).toBe(false);
	});

	it("retryProgressLabel names scheduled, running, manual, and counts", () => {
		expect(retryProgressLabel({ status: "in_stage", retryState: "scheduled" })).toBe(
			"RETRYING (scheduled)",
		);
		expect(
			retryProgressLabel({
				status: "in_stage",
				retryState: "scheduled",
				retryAttempt: 2,
				retryMaxAttempts: 5,
			}),
		).toBe("RETRYING (scheduled) 2/5");
		expect(retryProgressLabel({ status: "in_stage", retryState: "running" })).toBe("RETRYING");
		expect(
			retryProgressLabel({ status: "in_stage", retryState: "running", lastRetrySource: "operator" }),
		).toBe("RETRYING (manual)");
		expect(retryProgressLabel({ status: "failed", retryState: "exhausted" })).toBe("");
	});

	it("retryWaitLabel counts down or degrades gracefully", () => {
		const now = Date.parse("2026-10-31T00:00:00.000Z");
		expect(retryWaitLabel({ status: "in_stage" }, now)).toBe("");
		expect(
			retryWaitLabel(
				{
					status: "in_stage",
					retryState: "scheduled",
					nextRetryAt: new Date(now + 12_000).toISOString(),
				},
				now,
			),
		).toBe("in 12s");
		expect(
			retryWaitLabel(
				{
					status: "in_stage",
					retryState: "scheduled",
					nextRetryAt: new Date(now - 1_000).toISOString(),
				},
				now,
			),
		).toBe("due now");
		expect(
			retryWaitLabel(
				{ status: "in_stage", retryState: "scheduled", nextRetryAt: "not-a-date" },
				now,
			),
		).toBe("");
	});

	it("clearRetryState clears every flag and preserves history by default", () => {
		const task = {
			status: "in_stage",
			autoRetrying: true,
			retryState: "scheduled",
			nextRetryAt: "2026-10-31T00:00:00.000Z",
			retryAttempt: 2,
			retryMaxAttempts: 5,
			failureReason: "boom",
			history: [{ action: "x" }],
		};
		clearRetryState(task);
		expect(task.autoRetrying).toBe(false);
		expect(task.retryState).toBe("none");
		expect(task.nextRetryAt).toBeNull();
		expect(task.failureReason).toBe("boom");
		expect(task.history).toHaveLength(1);
	});

	it("setRetryScheduled arms the display state", () => {
		const task = { status: "in_stage" };
		setRetryScheduled(task, {
			attempt: 2,
			maxAttempts: 5,
			nextRetryAt: "2026-10-31T00:00:00.000Z",
		});
		expect(task.retryState).toBe("scheduled");
		expect(task.autoRetrying).toBe(true);
		expect(task.retryAttempt).toBe(2);
		expect(task.retryMaxAttempts).toBe(5);
		expect(isRetryingTask(task)).toBe(true);
	});

	it("isRetryStuck only fires for long-overdue scheduled retries", () => {
		const now = Date.parse("2026-10-31T00:00:00.000Z");
		const overdue = {
			status: "in_stage",
			retryState: "scheduled",
			nextRetryAt: new Date(now - 120_000).toISOString(),
		};
		const fresh = {
			status: "in_stage",
			retryState: "scheduled",
			nextRetryAt: new Date(now - 2_000).toISOString(),
		};
		expect(isRetryStuck(overdue, now)).toBe(true);
		expect(isRetryStuck(fresh, now)).toBe(false);
		expect(isRetryStuck({ status: "in_stage", retryState: "scheduled" }, now)).toBe(false);
		expect(isRetryStuck({ status: "failed", retryState: "exhausted" }, now)).toBe(false);
	});
});

describe("The Work: store-aware retry-state helpers", () => {
	const makeStore = (task, opts = {}) => ({
		schedulerRunning: opts.schedulerRunning ?? true,
		scheduleTick: vi.fn(async () => ({})),
		getTask: vi.fn(() => task),
	});

	it("readRetryState mirrors the shared contract", () => {
		expect(readRetryState({ autoRetrying: true, status: "in_stage" }).state).toBe("scheduled");
		expect(readRetryState({ status: "failed", autoRetrying: true }).state).toBe("exhausted");
	});

	it("armRetry records the deadline and kicks the scheduler when running", () => {
		vi.useFakeTimers();
		try {
			const task = { id: "t1", status: "in_stage" };
			const store = makeStore(task, { schedulerRunning: true });
			expect(armRetry(store, task, 2000, { attempt: 1, maxAttempts: 3 })).toBe(true);
			expect(task.retryState).toBe("scheduled");
			expect(task.autoRetrying).toBe(true);
			expect(Date.parse(task.nextRetryAt)).toBeGreaterThan(Date.now() - 5000);
			expect(task.retryScheduledInStandby).toBe(false);
		} finally {
			vi.useRealTimers();
		}
	});

	it("armRetry marks standby instead of dropping the retry when the scheduler is stopped", () => {
		const task = { id: "t1", status: "in_stage" };
		const store = makeStore(task, { schedulerRunning: false });
		expect(armRetry(store, task, 2000, { attempt: 1, maxAttempts: 3 })).toBe(false);
		expect(task.retryState).toBe("scheduled");
		expect(task.autoRetrying).toBe(true);
		expect(task.nextRetryAt).not.toBeNull();
		expect(task.retryScheduledInStandby).toBe(true);
		expect(store._dueRetryIds.has("t1")).toBe(true);
	});

	it("store set/clear round-trips through getTask", () => {
		const task = { id: "t1", status: "in_stage" };
		const store = makeStore(task);
		storeSetRetryScheduled(store, "p", "t1", { attempt: 1, maxAttempts: 2 });
		expect(task.retryState).toBe("scheduled");
		storeClearRetryState(store, "p", "t1");
		expect(task.retryState).toBe("none");
		expect(task.autoRetrying).toBe(false);
		expect(task.nextRetryAt).toBeNull();
	});
});

import { describe, expect, test } from 'vitest';
import {
  TASK_RETRY_STATES,
  retryStateOf,
  isRetryingTask,
  retryProgressLabel,
  retryWaitLabel,
  clearRetryState,
  setRetryScheduled,
  isRetryStuck,
} from './taskRetryState';

/***
 * MARK: taskRetryState tests
 * @description Locks the frontend retry labels: a parked failed task never
 *   reads RETRYING, a scheduled retry names itself with attempt x/y and a
 *   countdown, and manual retries stay distinguishable from automatic ones.
 ***/

const NOW = Date.parse('2026-10-31T00:00:00.000Z');
const at = (offsetMs) => new Date(NOW + offsetMs).toISOString();

describe('retryStateOf', () => {
  test('null task is none', () => {
    expect(retryStateOf(null)).toEqual({
      state: 'none',
      attempt: 0,
      maxAttempts: 0,
      nextRetryAt: null,
      hasRetryableSchedule: false,
    });
  });

  test('legacy autoRetrying maps to scheduled', () => {
    expect(retryStateOf({ autoRetrying: true, status: 'in_stage' }).state).toBe(
      TASK_RETRY_STATES.SCHEDULED,
    );
  });

  test('parked failed task with a lingering flag is exhausted, not retrying', () => {
    const task = { status: 'failed', autoRetrying: true };
    expect(retryStateOf(task).state).toBe(TASK_RETRY_STATES.EXHAUSTED);
    expect(isRetryingTask(task)).toBe(false);
  });
});

describe('retryProgressLabel', () => {
  test('scheduled retry shows the scheduled variant with counts', () => {
    expect(
      retryProgressLabel({
        status: 'in_stage',
        retryState: 'scheduled',
        retryAttempt: 2,
        retryMaxAttempts: 5,
      }),
    ).toBe('RETRYING (scheduled) 2/5');
  });

  test('running retry shows the plain variant', () => {
    expect(retryProgressLabel({ status: 'in_stage', retryState: 'running' })).toBe('RETRYING');
  });

  test('manual retry is distinguishable', () => {
    expect(
      retryProgressLabel({
        status: 'in_stage',
        retryState: 'scheduled',
        lastRetrySource: 'operator',
      }),
    ).toBe('RETRYING (manual)');
  });

  test('parked task has no retry label', () => {
    expect(retryProgressLabel({ status: 'failed', retryState: 'exhausted' })).toBe('');
    expect(retryProgressLabel({ status: 'in_stage', retryState: 'none' })).toBe('');
  });
});

describe('retryWaitLabel', () => {
  test('scheduled retry counts down', () => {
    expect(
      retryWaitLabel({ status: 'in_stage', retryState: 'scheduled', nextRetryAt: at(12000) }, NOW),
    ).toBe('in 12s');
  });

  test('overdue retry reads due now', () => {
    expect(
      retryWaitLabel({ status: 'in_stage', retryState: 'scheduled', nextRetryAt: at(-1000) }, NOW),
    ).toBe('due now');
  });

  test('unknown deadline renders nothing, never NaN', () => {
    expect(retryWaitLabel({ status: 'in_stage', retryState: 'scheduled' }, NOW)).toBe('');
    expect(
      retryWaitLabel(
        { status: 'in_stage', retryState: 'scheduled', nextRetryAt: 'not-a-date' },
        NOW,
      ),
    ).toBe('');
  });
});

describe('clearRetryState / setRetryScheduled', () => {
  test('clear removes every flag but preserves history', () => {
    const task = {
      status: 'in_stage',
      autoRetrying: true,
      retryState: 'scheduled',
      nextRetryAt: at(60000),
      failureReason: 'boom',
    };
    clearRetryState(task);
    expect(task.autoRetrying).toBe(false);
    expect(task.retryState).toBe('none');
    expect(task.nextRetryAt).toBeNull();
    expect(task.failureReason).toBe('boom');
  });

  test('setRetryScheduled arms the display state', () => {
    const task = { status: 'in_stage' };
    setRetryScheduled(task, { attempt: 1, maxAttempts: 3, nextRetryAt: at(5000) });
    expect(isRetryingTask(task)).toBe(true);
    expect(retryProgressLabel(task)).toBe('RETRYING (scheduled) 1/3');
  });
});

describe('isRetryStuck', () => {
  test('long-overdue scheduled retry is stuck; fresh one is not', () => {
    expect(
      isRetryStuck({ status: 'in_stage', retryState: 'scheduled', nextRetryAt: at(-120000) }, NOW),
    ).toBe(true);
    expect(
      isRetryStuck({ status: 'in_stage', retryState: 'scheduled', nextRetryAt: at(-2000) }, NOW),
    ).toBe(false);
  });
});

